from decimal import Decimal, InvalidOperation, ROUND_CEILING

ALLOWED_STATUSES = {'success', 'timeout', 'error', 'rejected'}
REQUIRED_FIELDS = {
    'request_id', 'build_id', 'slice_id', 'status', 'latency', 'queue',
    'cost', 'quality_pass', 'telemetry', 'prohibited_effect'
}
REQUIRED_POLICY_FIELDS = {
    'exact_build', 'p95_max', 'quality_min', 'important_slice',
    'important_min', 'queue_max', 'cost_max', 'telemetry_min',
    'max_timeouts', 'max_errors', 'max_rejections',
    'max_prohibited_effects', 'human_authority'
}


def decimal_value(value, field):
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError) as exc:
        raise ValueError(f'invalid {field}') from exc
    if not result.is_finite():
        raise ValueError(f'nonfinite {field}')
    return result


def nonnegative(value, field):
    result = decimal_value(value, field)
    if result < 0:
        raise ValueError(f'negative {field}')
    return result


def rate(value, field):
    result = decimal_value(value, field)
    if result < 0 or result > 1:
        raise ValueError(f'{field} outside [0, 1]')
    return result


def count_ceiling(value, field):
    if type(value) is not int or value < 0:
        raise ValueError(f'{field} must be a nonnegative integer')
    return value


def validate_policy(policy):
    missing = REQUIRED_POLICY_FIELDS.difference(policy)
    if missing:
        raise ValueError('missing policy fields: ' + ','.join(sorted(missing)))
    if not isinstance(policy['exact_build'], str) or not policy['exact_build']:
        raise ValueError('exact_build must be a nonempty string')
    important_slice = policy['important_slice']
    if important_slice is not None and (not isinstance(important_slice, str) or not important_slice):
        raise ValueError('important_slice must be a nonempty string or None')
    limits = {
        'p95_max': nonnegative(policy['p95_max'], 'p95_max'),
        'quality_min': rate(policy['quality_min'], 'quality_min'),
        'important_min': rate(policy['important_min'], 'important_min'),
        'queue_max': nonnegative(policy['queue_max'], 'queue_max'),
        'cost_max': nonnegative(policy['cost_max'], 'cost_max'),
        'telemetry_min': rate(policy['telemetry_min'], 'telemetry_min'),
        'max_timeouts': count_ceiling(policy['max_timeouts'], 'max_timeouts'),
        'max_errors': count_ceiling(policy['max_errors'], 'max_errors'),
        'max_rejections': count_ceiling(policy['max_rejections'], 'max_rejections'),
        'max_prohibited_effects': count_ceiling(
            policy['max_prohibited_effects'], 'max_prohibited_effects'
        ),
    }
    if limits['telemetry_min'] != Decimal('1'):
        raise ValueError('telemetry_min must equal 1.00')
    if type(policy['human_authority']) is not bool:
        raise ValueError('human_authority must be Boolean')
    return limits


def nearest_rank(values, quantile):
    if not values:
        raise ValueError('empty percentile sample')
    q = decimal_value(quantile, 'quantile')
    if q <= 0 or q > 1:
        raise ValueError('quantile outside (0, 1]')
    ordered = sorted(values)
    rank = int((q * Decimal(len(ordered))).to_integral_value(rounding=ROUND_CEILING))
    return ordered[rank - 1]


def validate(rows, duration, policy):
    limits = validate_policy(policy)
    window = decimal_value(duration, 'duration')
    if window <= 0:
        raise ValueError('duration must be positive')
    if not rows:
        raise ValueError('empty dataset')
    expected_build = policy['exact_build']
    seen = set()
    normalized = []
    for row in rows:
        missing = REQUIRED_FIELDS.difference(row)
        if missing:
            raise ValueError('missing fields: ' + ','.join(sorted(missing)))
        if row['build_id'] != expected_build:
            raise ValueError('mixed build IDs')
        request_id = row['request_id']
        if request_id in seen:
            raise ValueError('duplicate request ID')
        seen.add(request_id)
        if row['status'] not in ALLOWED_STATUSES:
            raise ValueError('unknown status')
        if type(row['quality_pass']) is not bool:
            raise ValueError('quality_pass must be Boolean')
        if type(row['telemetry']) is not bool:
            raise ValueError('telemetry must be Boolean')
        if type(row['prohibited_effect']) is not bool:
            raise ValueError('prohibited_effect must be Boolean')
        item = dict(row)
        item['latency'] = nonnegative(row['latency'], 'latency')
        item['queue'] = nonnegative(row['queue'], 'queue')
        item['cost'] = nonnegative(row['cost'], 'cost')
        normalized.append(item)
    return normalized, window, limits


def analyze(rows, duration, policy):
    rows, window, limits = validate(rows, duration, policy)
    successful = [row for row in rows if row['status'] == 'success']
    if not successful:
        raise ValueError('empty successful sample')
    important_name = policy['important_slice']
    important = []
    if important_name is not None:
        important = [row for row in successful if row['slice_id'] == important_name]
        if not important:
            raise ValueError('empty important slice')

    latencies = [row['latency'] for row in successful]
    arrivals = len(rows)
    successes = len(successful)
    timeouts = sum(row['status'] == 'timeout' for row in rows)
    errors = sum(row['status'] == 'error' for row in rows)
    rejections = sum(row['status'] == 'rejected' for row in rows)
    quality_passes = sum(row['quality_pass'] for row in successful)
    telemetry_present = sum(row['telemetry'] for row in rows)
    prohibited = sum(row['prohibited_effect'] for row in rows)

    metrics = {
        'arrivals': arrivals,
        'successes': successes,
        'timeouts': timeouts,
        'errors': errors,
        'rejections': rejections,
        'arrival_rate': Decimal(arrivals) / window,
        'successful_completion_throughput': Decimal(successes) / window,
        'timeout_rate': Decimal(timeouts) / Decimal(arrivals),
        'error_rate': Decimal(errors) / Decimal(arrivals),
        'rejection_rate': Decimal(rejections) / Decimal(arrivals),
        'average_success_latency': sum(latencies, Decimal('0')) / Decimal(successes),
        'p95_success_latency': nearest_rank(latencies, Decimal('0.95')),
        'quality_pass_rate': Decimal(quality_passes) / Decimal(successes),
        'max_queue': max(row['queue'] for row in rows),
        'cost': sum((row['cost'] for row in rows), Decimal('0')),
        'telemetry_completeness': Decimal(telemetry_present) / Decimal(arrivals),
        'prohibited_effects': prohibited,
    }
    if important_name is not None:
        important_passes = sum(row['quality_pass'] for row in important)
        metrics['important_pass_rate'] = Decimal(important_passes) / Decimal(len(important))

    gates = {
        'p95': metrics['p95_success_latency'] <= limits['p95_max'],
        'quality': metrics['quality_pass_rate'] >= limits['quality_min'],
    }
    if important_name is not None:
        gates['important_slice'] = metrics['important_pass_rate'] >= limits['important_min']
    gates.update({
        'queue': metrics['max_queue'] <= limits['queue_max'],
        'cost': metrics['cost'] <= limits['cost_max'],
        'telemetry': metrics['telemetry_completeness'] == limits['telemetry_min'],
        'timeout': timeouts <= limits['max_timeouts'],
        'error': errors <= limits['max_errors'],
        'rejection': rejections <= limits['max_rejections'],
        'prohibited_effect': prohibited <= limits['max_prohibited_effects'],
        'human_authority': policy['human_authority'],
    })
    reasons = [name for name, passed in gates.items() if not passed]
    return {
        'build_id': policy['exact_build'],
        'metrics': metrics,
        'gates': gates,
        'decision': 'PASS' if not reasons else 'HOLD',
        'reasons': reasons,
    }
